      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.10/open-walnut-0.6.10-darwin-arm64.tar.gz", using: :nounzip
      sha256 "1e7c74e5cea68ce100fe75d4e8c3f2ee964c412acf96df4cf11bbc63661ba5bc"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.10/open-walnut-0.6.10-darwin-x64.tar.gz", using: :nounzip
      sha256 "09adf18f721fac3e8e24f9c0fe866d73ba3301def43264233ee10bd6df258d44"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.10/open-walnut-0.6.10-linux-arm64.tar.gz", using: :nounzip
      sha256 "ae8f949992e7803436533feef00298e772def2205c04d9ea370333653c73755b"
    end
    on_intel do
      url "https://github.com/EvanZhang008/open-walnut/releases/download/v0.6.10/open-walnut-0.6.10-linux-x64.tar.gz", using: :nounzip
      sha256 "1a90de6db4f14886d5b59562ef568289738e9d56a7785406b8c3b144f25e684b"
    end
  end

  def install
    libexec.install Dir["open-walnut-*.tar.gz"].first => "open-walnut.tar.gz"
    # Scripts, not links: the cleaner drops a link whose target is not there yet.
    bin.write_exec_script libexec/"app/bin/walnut", libexec/"app/bin/open-walnut"
  end

  # After Homebrew's install-name pass over the keg, which the archive must skip.
  # The packed copy goes once unpacked, so running these again changes nothing.
  post_install_steps do
    if_path_exists "open-walnut.tar.gz", base: :libexec do
      remove "app", base: :libexec, recursive: true
      mkdir_p "app", base: :libexec
      run "tar", args: ["-xzf", "{{libexec}}/open-walnut.tar.gz", "-C", "{{libexec}}/app", "--strip-components=1"],
                 writable_paths: ["app"], writable_base: :libexec
      remove "open-walnut.tar.gz", base: :libexec
    end
  end

  def caveats
    <<~EOS
      Start it with:
        walnut web
      Walnut keeps itself up to date: it installs new releases when it starts.
      Its sessions run Claude Code: https://claude.com/product/claude-code
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/walnut --version")
  end
end
